// Fixtures were generated by the real engine at 1cb6bd98 using the v0.4.5
// artifact payloads, with legacy version-key aliases and the mongosh entry
// required by that engine's initialization. No old payload was replaced.
// No member is first converged or prepared by the current control plane.
func TestCPUpgradePreservesPreparedMembers(t *testing.T) {
	for _, version := range []string{"1.39.12", "1.40.1"} {
		t.Run(version, func(t *testing.T) {
			f := coreSetup(t, 1)
			p, rc := f.p, f.rc
			fixture := enginetest.RestorePreparedCPUpgrade(t, rc, fmt.Sprintf("testdata/cp-upgrade-%s.json", version))
			if !strings.Contains(strings.Join(fixture.Runtime.Prepare, "\n"), "weaviate-"+version) {
				t.Fatal("fixture lacks genuine preparation for the old Weaviate release")
			}
			rc.Backend = &cpUpgradeBackend{Backend: f.backend, services: enginetest.PreparedServices(fixture)}
			beforeCalls := len(f.backend.Calls())
			var names []string
			for name := range fixture.Configs {
				names = append(names, name)
			}
			rc.Dialer = coreDialer{enginetest.LegacyNativeServer(t, fixture.Secrets[secretCA], fixture.Secrets[secretCAKey], names, f.native.Config.Handler)}
			for range 3 {
				p = New(p.options)
				f.p = p
				if _, err := p.Sync(t.Context(), rc); err != nil {
					t.Fatal(err)
				}
			}
			state, err := load(rc.Cluster)
			if err != nil {
				t.Fatal(err)
			}
			if state.Rolling != nil || state.Pending != nil || state.Phase != "ready" {
				t.Fatal("CP-only upgrade scheduled a config/version rollout")
			}
			for name, before := range fixture.Configs {
				after, err := p.MemberConfig(t.Context(), rc, name)
				if err != nil {
					t.Fatal(err)
				}
				enginetest.RequirePreparedConfig(t, name, before.EngineSpec, after.EngineSpec)
			}
			for _, call := range f.backend.Calls()[beforeCalls:] {
				if call == "Deploy" {
					t.Fatal("CP-only upgrade redeployed existing member")
				}
			}
		})
	}
}

// Existing native services are observations, not freshly imported resources.
// Mutations still reach the ordinary fake backend and its call recorder.
type cpUpgradeBackend struct {
	*fake.Backend
	services map[string]*infra.Service
}

func (b *cpUpgradeBackend) GetService(_ context.Context, name string) (*infra.Service, error) {
	return b.services[name], nil
}

func (b *cpUpgradeBackend) ListServices(context.Context, string) ([]infra.Service, error) {
	var services []infra.Service
	for _, service := range b.services {
		services = append(services, *service)
	}
	return services, nil
}

func (b *cpUpgradeBackend) Containers(_ context.Context, name string) ([]infra.Container, error) {
	return []infra.Container{{ID: name + "-instance", Status: infra.ContainerActive}}, nil
}
